      border-radius: var(--radius);
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .preview {
      padding: 20px;
    }

    .preview-frame {
      position: relative;
      aspect-ratio: 4 / 5;
      border-radius: 20px;
      overflow: hidden;
      background: linear-gradient(160deg, #172036 0%, #090d18 100%);
      border: 1px solid rgba(148, 163, 184, 0.16);
    }

    .preview-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
    }

    .preview-chip {
      position: absolute;
      top: 16px;
      left: 16px;
      padding: 10px 12px;
      border-radius: 999px;
      background: rgba(15, 23, 42, 0.72);
      border: 1px solid rgba(255, 255, 255, 0.08);
      font-size: 0.82rem;
      color: #dbeafe;
      backdrop-filter: blur(14px);
    }

    .details {
      padding: 24px 4px 4px;
    }

    .title-row {
      display: flex;
