      margin: 0;
      font-size: 1.6rem;
      letter-spacing: -0.03em;
    }

    .subtle {
      margin: 8px 0 18px;
      color: var(--muted);
      line-height: 1.6;
    }

    .meta-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      margin-bottom: 22px;
    }

    .meta-item {
      padding: 14px;
      border-radius: 18px;
      background: rgba(148, 163, 184, 0.08);
      border: 1px solid rgba(148, 163, 184, 0.1);
    }

    .meta-item span {
      display: block;
      color: var(--muted);
      font-size: 0.8rem;
      margin-bottom: 4px;
    }

    .meta-item strong {
      font-size: 0.98rem;
      font-weight: 600;
    }

    .actions {
      display: flex;
      gap: 12px;
      padding-top: 10px;
      border-top: 1px solid rgba(148, 163, 184, 0.12);
    }

    button {
      appearance: none;
      border: 0;
      cursor: pointer;
      font: inherit;
      transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    .btn {
      padding: 13px 18px;
      border-radius: 16px;
      font-weight: 600;
    }

    .btn-secondary {
      color: var(--text);
      background: rgba(148, 163, 184, 0.12);
      border: 1px solid rgba(148, 163, 184, 0.12);
    }

    .btn-danger {
      color: white;
      background: linear-gradient(135deg, #f87171, #dc2626);
      box-shadow: 0 16px 30px rgba(220, 38, 38, 0.28);
    }

    .btn-danger-muted {
      color: #fecaca;
      background: var(--danger-soft);
      border: 1px solid rgba(239, 68, 68, 0.18);
    }

    .modal-root[hidden] {
      display: none;
    }

    .modal-root {
      position: fixed;
      inset: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      z-index: 10;
    }

    .modal-backdrop {
      position: absolute;
      inset: 0;
      background: rgba(2, 6, 23, 0.62);
      backdrop-filter: blur(10px);
    }

    .dialog {
      position: relative;
      width: min(100%, 480px);
      padding: 24px;
      border-radius: 24px;
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.96));
      border: 1px solid rgba(148, 163, 184, 0.16);
      box-shadow: var(--shadow);
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      border-radius: 16px;
      background: var(--danger-soft);
      color: #fca5a5;
      margin-bottom: 18px;
      font-size: 1.4rem;
    }

    .dialog h3 {
      margin: 0 0 10px;
      font-size: 1.45rem;
      letter-spacing: -0.03em;
    }

    .dialog p {
      margin: 0;
      color: var(--muted);
