          <rect x="146" y="242" width="240" height="10" rx="5" fill="rgba(255,255,255,0.18)" />
        </svg>
      `);

    function Button({ className = "", label, type = "button", dataAction = "" }) {
      const button = document.createElement("button");
      button.type = type;
      button.className = className;
      if (dataAction) {
        button.dataset.action = dataAction;
      }
      button.textContent = label;
      return button;
    }

    function Header() {
      const section = document.createElement("section");
      section.className = "hero";
      section.innerHTML = `
        <div class="eyebrow">Media Library</div>
        <h1>Preview before you publish.</h1>
        <p>
          Review image details, keep your gallery organized, and confirm destructive actions with a
          focused modal dialog that feels at home in a modern product UI.
        </p>
      `;
      return section;
    }

    function ImagePreviewCard(onDeleteClick) {
      const card = document.createElement("section");
      card.className = "card preview";
      card.innerHTML = `
        <div class="preview-frame">
          <img src="${imageSrc}" alt="Aurora sky gradient artwork preview">
          <div class="preview-chip">Featured cover image</div>
        </div>
        <div class="details">
          <div class="title-row">
