            <div class="meta-item">
              <span>Last edited</span>
              <strong>2 hours ago</strong>
            </div>
          </div>
        </div>
      `;

      const actions = document.createElement("div");
      actions.className = "actions";

      actions.append(
        Button({ className: "btn btn-secondary", label: "Keep image" }),
        Button({
          className: "btn btn-danger-muted trigger",
          label: "Delete image",
          dataAction: "open-dialog"
        })
      );

      actions.querySelector('[data-action="open-dialog"]').addEventListener("click", onDeleteClick);
      card.querySelector(".details").append(actions);
      return card;
