      const actions = modal.querySelector(".dialog-actions");
      const cancelButton = Button({ className: "btn btn-secondary", label: "Cancel", dataAction: "cancel" });
      const confirmButton = Button({ className: "btn btn-danger", label: "Delete from library", dataAction: "confirm" });
      actions.append(cancelButton, confirmButton);

      modal.querySelectorAll('[data-action="cancel"]').forEach((element) => {
        element.addEventListener("click", onCancel);
      });

      confirmButton.addEventListener("click", onConfirm);

      modal.addEventListener("keydown", (event) => {
        if (event.key === "Escape") {
          onCancel();
        }
      });

      return modal;
    }

    function App() {
      let dialogOpen = false;

