      const dialog = ConfirmDeleteDialog({ onCancel: handleCancel, onConfirm: handleConfirm });

      const triggerButton = preview.querySelector(".trigger");
      const confirmDeleteButton = dialog.querySelector('[data-action="confirm"]');

      const status = document.createElement("p");
      status.className = "sr-only";
